(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  [...document.querySelectorAll('.tb-actions button')].find((b) => b.textContent.trim() === '备份与恢复')?.click();
  await sleep(1500);
  return JSON.stringify({ modalOpen: !!document.querySelector('.bk-modal'), fileInputReady: !!document.querySelector('.bk-modal input[type=file]') });
})()
